function data_corr = fun_coil_uniform(data, filepath)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Function: fun_coil_uniform_convert_h5
% Purpose: 
%   1. Write the input reconstructed data to an H5 file (split into real/imag parts)
%   2. Execute Python script for coil uniformity correction
%   3. Read the corrected H5 file generated by the Python script
% Inputs:
%   - data: The input data to be processed with coil uniformity correction
%   - filepath: Full path (including filename) to save the intermediate H5 file
% Output:
%   - data_corr: Corrected data after coil uniformity adjustment (complex number)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Save data to H5 file
tic % Start timing
% Check if the target H5 file exists, delete it if present
if exist(filepath, 'file')==2  % '2' means the file exists
    delete(filepath);  % Remove the existing file
    % disp(['File "', filepath, '" has been deleted successfully']);
end

% Write real part of the complex data to H5
h5create(filepath,'/data_real', size(real(data)));
h5write(filepath,'/data_real', real(data));

% Write imaginary part of the complex data to H5
h5create(filepath,'/data_imag', size(imag(data)));
h5write(filepath,'/data_imag', imag(data));

%% Execute Python coil uniformity correction script
python_script = '/bin/coil_uniform/CoilUniform_v2.py';
data_path = filepath;  % Path to the H5 file created above

% Build command to activate conda environment and run Python script (Windows CMD)
% Note: Use & to chain commands in Windows CMD
cmd = sprintf([
    'cmd /c "conda activate mri_basic & ', ...
    'python "%s" "%s""' ...
    ], python_script, data_path);

% Execute the command and capture status/result
[status, result] = system(cmd);

% Check execution status and print feedback
if status ~= 0
    fprintf('Coil Uniform Correction Error:\n%s\n', result);
else
    fprintf('Coil Uniform Correction Completed Successfully:\n%s\n', result);
end

%% Read the corrected H5 file
[pathstr, name, ~] = fileparts(filepath);
corrcu_filepath = fullfile(pathstr, name) + "_corrected.h5";  % Corrected file path

% Read real and imaginary parts of corrected data
data_corrcu_real = h5read(corrcu_filepath, '/data_real');
data_corrcu_imag = h5read(corrcu_filepath, '/data_imag');

% Combine real and imaginary parts to form complex corrected data
data_corr = data_corrcu_real + 1i * data_corrcu_imag;

toc % End timing
end